parameters.jsCode:
const candidates = [$json.body, $json.body?.data, $json.body?.fields, $json.data, $json.fields, $json];
const fieldKeys = ['name', 'fullName', 'Full name', 'email', 'emailAddress', 'Email address'];
const body = candidates.find((candidate) => {
  return candidate &&
    typeof candidate === 'object' &&
    !Array.isArray(candidate) &&
    fieldKeys.some((field) => candidate[field] !== undefined);
}) ?? {};

const name = String(body.name ?? body.fullName ?? body['Full name'] ?? '').trim();
const email = String(body.email ?? body.emailAddress ?? body['Email address'] ?? '').trim().toLowerCase();
const phone = String(body.phone ?? body.mobilePhone ?? body['Mobile phone'] ?? '').trim();
const topic = String(body.topic ?? body.enquiryType ?? body['Type of enquiry'] ?? '').trim();
const message = String(body.message ?? body.details ?? body.Details ?? '').trim();

const requiredValues = { name, email, phone, topic, message };
const missingFields = Object.entries(requiredValues)
  .filter(([, value]) => !value)
  .map(([field]) => field);

if (missingFields.length > 0) {
  throw new Error(`Missing required fields: ${missingFields.join(', ')}`);
}

if (body.consent !== true && body.consent !== 'true' && body.consent !== 'on') {
  throw new Error('Consent is required');
}

const submissionId = String(
  body.submissionId ?? body['Submission ID'] ?? `contact-${Date.now()}`
);
const [firstName, ...lastNameParts] = name.split(/\s+/);
const lastName = lastNameParts.join(' ');
const preferredBranch = body.preferredBranch || body['Preferred branch'] || 'unknown';
const source = body.source || 'webflow-contact-page';

return [{
  json: {
    provider: 'gencode-crm',
    submissionId,
    source,
    receivedAt: new Date().toISOString(),
    contact: {
      name,
      firstName: firstName || name,
      lastName,
      email,
      phone,
      title: body.title || '',
      ownerType: body.ownerType || ''
    },
    enquiry: {
      topic,
      message,
      preferredBranch,
      vehicleModel: body.vehicleModel || body.Model || '',
      yearOfPurchase: body.yearOfPurchase || body['Year of purchase'] || ''
    },
    crmPayload: {
      name: {
        firstName: firstName || name,
        lastName
      },
      emails: {
        primaryEmail: email,
        additionalEmails: []
      },
      phones: {
        primaryPhoneNumber: phone,
        primaryPhoneCountryCode: '',
        additionalPhones: []
      },
      city: preferredBranch === 'unknown' ? null : preferredBranch,
      intro: message,
      jobTitle: `Website enquiry: ${topic}`
    }
  }
}];

